const M=require('../src/models');const fs=require('fs'),path=require('path'),assert=require('assert/strict');const {recordBusinessAction}=require('../src/utils/businessActionLog');
const no='ORD202610230731057622',batch='ORDER-STORE-20261104-'+no,target='D028000';
(async()=>{let backup;await M.sequelize.transaction(async transaction=>{const opt={transaction,lock:transaction.LOCK.UPDATE};const o=await M.Order.findOne({where:{order_no:no},...opt});assert.equal(o.store_id,'D0216646');assert.equal(o.is_deleted,0);const s=await M.Store.findByPk(target,opt);assert(s.status===1&&!s.is_deleted&&s.distributor_id==='DIST001');const period=await M.ExpenseAccountingPeriod.findOne({where:{distributor_id:'DIST001',month_key:'2026-10'},...opt});assert(!period||period.status==='open');for(const [k,w] of [['SalesReturnRequest',{order_id:o.order_id}],['SalesReturnGrossProfitLedger',{order_id:o.order_id}],['PerformanceProfitAdjustment',{order_id:o.order_id}],['SalesSettlementCostAdjustment',{sales_order_id:o.order_id}]])assert.equal(await M[k].count({where:w,transaction}),0);const p=await M.OrderGrossProfit.findOne({where:{order_id:o.order_id},...opt});const settlements=await M.ProductSettlementOrder.findAll({where:{source_order_id:o.order_id},...opt});assert(p&&p.snapshot_status==='final');assert.equal(p.store_id,o.store_id);assert.equal(settlements.length,1);assert.equal(settlements[0].store_id,o.store_id);const daily=await M.DailyStatementDetail.findAll({where:{order_id:o.order_id},...opt});backup={batch,order:o.toJSON(),profit:p.toJSON(),settlements:settlements.map(x=>x.toJSON()),daily:daily.map(x=>x.toJSON()),target:s.toJSON()};const dir=path.resolve(__dirname,'../backup/order-store-corrections');fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,batch+'.json'),JSON.stringify(backup,null,2),{flag:'wx'});await o.update({store_id:target},{transaction});await p.update({store_id:target},{transaction});for(const x of settlements)await x.update({store_id:target},{transaction});await recordBusinessAction({businessType:'sales_order',businessId:o.order_id,businessNo:no,action:'correct_store_attribution',user:{name:'用户授权（Codex会话）'},comment:batch,detail:{from:'D0216646',to:target,salesProfit:p.gross_profit_amount,productProfit:settlements[0].gross_profit_amount,settledDailyPreserved:true,authorization:'用户要求订单转自营仓并同步毛利，明确直接修改'},transaction});});for(const [k,id,b]of [['Order',backup.order.order_id,backup.order],['OrderGrossProfit',backup.profit.gross_profit_id,backup.profit],['ProductSettlementOrder',backup.settlements[0].settlement_id,backup.settlements[0]]]){const r=JSON.parse(JSON.stringify(await M[k].findByPk(id,{raw:true})));assert.equal(r.store_id,target);for(const key of Object.keys(b))if(!['store_id','update_time'].includes(key))assert.deepEqual(r[key],b[key],k+'.'+key);}assert.deepEqual(JSON.parse(JSON.stringify(await M.DailyStatementDetail.findAll({where:{order_id:backup.order.order_id},raw:true}))),backup.daily);console.log(JSON.stringify({verified:true,batch,store:target,salesProfit:backup.profit.gross_profit_amount,productProfit:backup.settlements[0].gross_profit_amount,settledDailyPreserved:true}));})().catch(e=>{console.error(e);process.exitCode=1}).finally(()=>M.sequelize.close());
